from lib import *
S = SS('q7')
steps = [
    step("RabbitMQ 4.3.6 默认就不让你建“非持久、非排他”的队列:声明 durable=False 的普通队列,broker 回 541 INTERNAL_ERROR,说 feature transient_nonexcl_queues is deprecated——而且是整条连接被关,不只是 channel。exclusive=True 的非持久队列(随连接消失)和“服务器命名 + exclusive + auto_delete”的队列仍然可以。要演示非持久队列只能在配置里加 deprecated_features.permit.transient_nonexcl_queues = true,下面几节都是这样配置的。", t=tl(S(1)), mark=lidx(S(1), '默认配置下 durable=False', '整条连接被关'), done=lidx(S(1), 'exclusive=True 的非持久队列', '服务器命名'), kv=KV([['非持久 + 非排他', '默认被拒,整条连接被关(541)'], ['非持久 + 排他', '仍可用,随连接消失'], ['放开', 'deprecated_features.permit.transient_nonexcl_queues = true']], ['非持久 + 非排他'])),
    step("2×2 矩阵:队列 durable / 非 durable × 消息 persistent(delivery_mode=2)/ transient(1),各发 100 条,重启前四个队列都是 100 条。正常关闭再启动后:只剩 dq.p(持久队列 + 持久消息)100 条;dq.t(持久队列 + 非持久消息)队列还在但 0 条;两个非持久队列 tq.p、tq.t 连队列本身都没了——即使里面的消息标了 persistent。persistent 要同时具备“队列是 durable”才有意义。", t=tl(S(2)), mark=lidx(S(2), '正常重启后'), done=lidx(S(2), '重启前', '规则'), b=bars([['dq.p 持久队列+持久消息', 100, '100 条'], ['dq.t 持久队列+非持久消息', 0, '0 条'], ['tq.p 非持久队列+持久消息', 0, '队列已消失'], ['tq.t 非持久队列+非持久消息', 0, '队列已消失']], 100, mark=[1, 2, 3], done=[0]), kv=KV([['需要同时满足', '队列 durable + 消息 persistent'], ['只有一个满足', '都不保留消息'], ['非持久队列', '重启后队列本身也不在']], ['需要同时满足'])),
    step("kill -9(不走关闭流程)的结果:持久队列、持久消息、发 5000 条。发完马上 kill -9(不等任何确认):重启后 kq 里只有 4080 条;每条都等 confirm、全部回来后再 kill -9:5000 条全在;发完等 2 秒再 kill -9:5000 条也全在。未确认的发布在 broker 被杀时可能丢,收到 confirm 的不会。要说明的是 kill -9 只杀进程,操作系统页缓存里的数据还在,真正的掉电或内核崩溃丢数据在这台笔记本上测不到。", t=tl(S(3)), mark=lidx(S(3), '发完马上 kill -9'), done=lidx(S(3), '每条等 confirm', '发完等 2 秒再', '注意:kill -9'), b=bars([['发完马上 kill -9', 4080, '4080 条'], ['等 confirm 后 kill', 5000, '5000 条'], ['等 2 秒后 kill', 5000, '5000 条']], 5000, mark=[0], done=[1, 2]), kv=KV([['没确认就杀', '少了一部分'], ['confirm 回来后再杀', '一条不丢'], ['未测', '掉电 / 内核崩溃']], ['没确认就杀'])),
    step("磁盘上:往持久队列发 20000 条 1 KB 的消息,persistent 的增长 24844 KiB,transient 的增长 24852 KiB——几乎一样。在 4.3.6 里每个队列有自己的目录(msg_store_persistent 和 msg_store_transient 都是 0 KiB,queues 目录 49704 KiB,两个队列各约 24 MiB),里面是队列索引 .qi 和消息存储 .qs 文件;小消息不进共享的消息存储,而是直接写进队列自己的文件,不论消息是不是 persistent。所以 transient 消息不是“只在内存里”,区别在于重启时不会被恢复。", t=tl(S(4)), mark=lidx(S(4), 'persistent 20000 条', 'vhost 数据目录'), done=lidx(S(4), '基线', '每个队列一个子目录'), b=bars([['persistent 20000×1KB', 24844, '24844 KiB'], ['transient 20000×1KB', 24852, '24852 KiB']], 24852, mark=[1], done=[0]), kv=KV([['persistent 消息', '写队列自己的 .qs / .qi'], ['transient 消息', '同样写盘,重启后不恢复'], ['共享消息存储', '这个大小的消息用不上']], ['transient 消息'])),
    step("durable 队列绑在非 durable 的 exchange 上,正常重启后:exchange x.transient(durable=false)和 x.durable(durable=true)都还在,x.transient → dq.bind 的绑定也在;被删的是非持久队列 tq.bind,它在两个 exchange 上的绑定跟着没了。往 x.transient 发布依然能路由到 dq.bind(现在 1 条);再 kill -9 重启,两个 exchange 和绑定仍在。也就是说在 4.3.6 里“非持久 exchange”重启后没有消失——和我印象里的旧说法不一样,只有非持久队列会被清掉。", t=tl(S(5)), mark=lidx(S(5), '正常重启后 exchange', '再 kill -9 重启后'), done=lidx(S(5), '重启前 exchange', '重启后的队列', '向 x.transient 发布'), kv=KV([['非持久队列', '重启后连同绑定一起消失'], ['durable=false 的 exchange', '在 4.3.6 里仍在'], ['kill -9 后', '结果相同']], ['durable=false 的 exchange'])),
]
A = mkartq('q7', 7, 'RabbitMQ,持久化,durable,persistent,delivery_mode,kill -9,真实验证,动画演示',
    '在 RabbitMQ 4.3.6 上实测持久化:默认拒绝非持久非排他队列(541);队列 durable 与消息 persistent 要同时满足重启后才保留;kill -9 时没等 confirm 的 5000 条只剩 4080 条,等了 confirm 的 5000 条全在;persistent 与 transient 消息写盘量几乎一样;非持久 exchange 在 4.3.6 里重启后仍在。',
    '“消息持久化”到底是几个开关?只设 delivery_mode=2 够不够?kill -9 之后会丢多少?transient 消息是不是只在内存里?durable 队列绑在非 durable 的 exchange 上重启会怎样?这篇用真的重启和真的 kill -9 来验证。',
    [('541', '默认配置下声明非持久、非排他队列,broker 关掉整条连接的错误码'), ('4080 / 5000', '发完马上 kill -9 时留下的持久消息数(等 confirm 后再杀则 5000 / 5000)'), ('24844 vs 24852 KiB', '20000 条 1 KB 的 persistent 与 transient 消息的磁盘增长,几乎相同')],
    [('默认的限制', '<p>RabbitMQ 4.3.6 默认不允许声明“非持久、非排他”的队列(541 INTERNAL_ERROR,整条连接被关),只有 exclusive 的非持久队列可以。想做非持久队列的实验要在配置里打开 <code>deprecated_features.permit.transient_nonexcl_queues</code>。</p>'),
     ('两个开关', '<p>队列要 <code>durable</code>、消息要 <code>delivery_mode=2</code>,重启后消息才保留。只满足一个不行:非持久队列重启后连队列都没了,持久队列里的 transient 消息被清空。RabbitMQ 4.x 还默认禁止建非持久、非排他的队列。</p>'),
     ('kill -9', '<p>没等 confirm 的发布在 broker 被杀时可能没处理完;收到 confirm 的不会丢。这里 kill -9 杀的是进程,操作系统缓存里的写入仍在,所以断电的情况需要另外的试验(没有测)。</p>'),
     ('磁盘', '<p>4.3.6 的经典队列把小消息直接写进自己目录里的 <code>.qs</code> 文件,索引放 <code>.qi</code>;transient 消息同样写盘,只是重启时不被恢复。所以 transient 并不意味着不占磁盘。</p>'),
     ('exchange 与绑定', '<p>非持久队列被清掉时,它的绑定也一起消失;而 <code>durable=false</code> 的 exchange 在 4.3.6 里重启后还在,绑定到持久队列的那条也保留。(这与较早版本的说法不同,以实测为准。)</p>')],
    steps,
    [ENV_Q + '。第二、五节用 rabbitmqctl shutdown 正常关闭再启动,第三、五节另用 kill -9;队列的消息数来自 rabbitmqctl list_queues;第四节磁盘大小用 du -sk 数据目录,发布后等 2 秒;非持久队列的实验在配置里开了 deprecated_features.permit.transient_nonexcl_queues',
     '没有验证:掉电或内核崩溃(fsync 是否真的落盘;macOS 的 fsync 不保证);quorum 队列和 stream 的持久化(见后面);Linux 上的磁盘写入量与延迟;更大的消息(超过队列自己存储的阈值)是否走共享消息存储;集群里节点之间的持久化;kill -9 时“丢 920 条”的具体比例每次会不同,没有统计'],
    '持久化')
